macro_rules! check_static_item {
    () => {
        # [instrument (level = "debug" , skip (tcx))] pub (crate) fn check_static_item < 'tcx > (tcx : TyCtxt < 'tcx > , item_id : LocalDefId , ty : Ty < 'tcx > , should_check_for_sync : bool ,) -> Result < () , ErrorGuaranteed > { enter_wf_checking_ctxt (tcx , item_id , | wfcx | { let span = tcx . ty_span (item_id) ; let item_ty = wfcx . deeply_normalize (span , Some (WellFormedLoc :: Ty (item_id)) , ty) ; let is_foreign_item = tcx . is_foreign_item (item_id) ; let forbid_unsized = ! is_foreign_item || { let tail = tcx . struct_tail_for_codegen (item_ty , wfcx . infcx . typing_env (wfcx . param_env)) ; ! matches ! (tail . kind () , ty :: Foreign (_)) } ; wfcx . register_wf_obligation (span , Some (WellFormedLoc :: Ty (item_id)) , item_ty . into ()) ; if forbid_unsized { let span = tcx . def_span (item_id) ; wfcx . register_bound (traits :: ObligationCause :: new (span , wfcx . body_def_id , ObligationCauseCode :: SizedConstOrStatic ,) , wfcx . param_env , item_ty , tcx . require_lang_item (LangItem :: Sized , span) ,) ; } let should_check_for_sync = should_check_for_sync && ! is_foreign_item && tcx . static_mutability (item_id . to_def_id ()) == Some (hir :: Mutability :: Not) && ! tcx . is_thread_local_static (item_id . to_def_id ()) ; if should_check_for_sync { wfcx . register_bound (traits :: ObligationCause :: new (span , wfcx . body_def_id , ObligationCauseCode :: SharedStatic ,) , wfcx . param_env , item_ty , tcx . require_lang_item (LangItem :: Sync , span) ,) ; } Ok (()) }) }
    };
}

check_static_item!();